/**
 * Bridge for EvolutionModal lifecycle (cinematic + fusion-short).
 */

import { awaitLazyModalReady } from '../lib/lazyModalMounts.ts';

export type EvolutionModalMode = 'cinematic' | 'fusion-short';

export interface EvolutionModalPayload {
  mode: EvolutionModalMode;
  oldName: string;
  newName: string;
  oldDisplayName: string;
  newDisplayName: string;
  oldSpriteUrl: string;
  newSpriteUrl: string;
  isShiny: boolean;
  reducedMotion: boolean;
  whatText: string;
  congratsText: string;
  fusionTitle?: string;
  fusionBody?: string;
  confirmLabel: string;
  onComplete?: () => void;
}

type ShowFn = (data: EvolutionModalPayload) => void;
type CloseFn = () => void;

let _show: ShowFn | null = null;
let _close: CloseFn | null = null;
let _canDismiss: () => boolean = () => true;
let _pendingOnComplete: (() => void) | null = null;
let _pendingQueue: EvolutionModalPayload[] = [];

function flushPendingEvolutionShow(): void {
  if (typeof _show !== 'function' || _pendingQueue.length === 0) return;
  const items = _pendingQueue.splice(0);
  for (const payload of items) {
    try {
      _show(payload);
    } catch (err) {
      console.error('[evolutionModalBridge] error in show callback:', err);
    }
  }
}

export function setEvolutionModalShow(fn: ShowFn | null | undefined): void {
  _show = typeof fn === 'function' ? fn : null;
  flushPendingEvolutionShow();
}

export function setEvolutionModalClose(fn: CloseFn | null | undefined): void {
  _close = typeof fn === 'function' ? fn : null;
}

export function setEvolutionModalCanDismiss(fn: (() => boolean) | null | undefined): void {
  _canDismiss = typeof fn === 'function' ? fn : () => true;
}

export async function showEvolutionCinematic(data: EvolutionModalPayload): Promise<void> {
  await awaitLazyModalReady('evolutionModal');
  _pendingOnComplete = data.onComplete ?? null;
  const payload = { ...data, mode: 'cinematic' as const };
  if (typeof _show === 'function') {
    try {
      _show(payload);
    } catch (err) {
      console.error('[evolutionModalBridge] error in show callback:', err);
    }
  } else {
    _pendingQueue.push(payload);
  }
}

export async function showEvolutionFusionShort(
  data: Omit<EvolutionModalPayload, 'mode' | 'onComplete'>,
): Promise<void> {
  await awaitLazyModalReady('evolutionModal');
  _pendingOnComplete = null;
  const payload = { ...data, mode: 'fusion-short' as const, onComplete: undefined };
  if (typeof _show === 'function') {
    try {
      _show(payload);
    } catch (err) {
      console.error('[evolutionModalBridge] error in show callback:', err);
    }
  } else {
    _pendingQueue.push(payload);
  }
}

export function closeEvolutionModal(): void {
  try {
    if (!_canDismiss()) return;
  } catch (err) {
    console.error('[evolutionModalBridge] error evaluating canDismiss gate:', err);
    return;
  }
  try {
    _close?.();
  } catch (err) {
    console.error('[evolutionModalBridge] error in close callback:', err);
  }
}

export function runEvolutionModalOnComplete(): void {
  const fn = _pendingOnComplete;
  _pendingOnComplete = null;
  if (typeof fn === 'function') {
    try {
      fn();
    } catch (err) {
      console.error('[evolutionModalBridge] error in onComplete callback:', err);
    }
  }
}

export function peekEvolutionModalOnComplete(): (() => void) | null {
  return _pendingOnComplete;
}

/** @internal Vitest only */
export function _resetEvolutionModalBridgeForTests(): void {
  _show = null;
  _close = null;
  _canDismiss = () => true;
  _pendingOnComplete = null;
  _pendingQueue = [];
}

if (typeof globalThis !== 'undefined') {
  (globalThis as Record<string, unknown>).__showEvolutionModal = showEvolutionCinematic;
  (globalThis as Record<string, unknown>).__showEvolutionFusionShort = showEvolutionFusionShort;
  (globalThis as Record<string, unknown>).__closeEvolutionModal = closeEvolutionModal;
}
